/* ATLAS V1 — site public + carnets privés. Aucun secret dans le navigateur. */
(()=>{'use strict';
const ROOT=document.getElementById('app-root'), MOD=document.getElementById('modal-root'), TOAST=document.getElementById('toaster');
const CONFIG=window.ATLAS_CONFIG||{};const configured=!!(CONFIG.supabaseUrl&&CONFIG.supabaseAnonKey&&window.supabase?.createClient);
const cloud=configured?window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
const KEY='atlas-v1-demo-2026'; const TERR=[{id:'autonomie',name:'Autonomie',symbol:'✧',image:'assets/autonomie.webp',question:'Comment devenir libre de choisir ?',desc:'Épargne, indépendance, logement et liberté de décider.'},{id:'corps',name:'Corps',symbol:'☼',image:'assets/corps.webp',question:'Que suis-je capable de vivre avec mon corps ?',desc:'Mouvement, santé, énergie, confiance et exploration.'},{id:'esprit',name:'Esprit',symbol:'☽',image:'assets/esprit.webp',question:'Comment comprendre le monde et moi-même ?',desc:'Philosophie, psychologie, culture et esprit critique.'},{id:'savoir',name:'Savoir-faire',symbol:'❧',image:'assets/savoir-faire.webp',question:'Qu’est-ce que je peux apprendre à faire ?',desc:'Cuisine, rénovation, création, jardin et compétences concrètes.'}];
const FOUNDER=[{id:'premier-bien',territory:'autonomie',title:'Premier Bien',type:'Mission',summary:'Acheter et rénover mon premier bien immobilier en partant de zéro.',detail:'Devenir plus autonome financièrement et apprendre, étape après étape, à comprendre l’immobilier. Je documenterai mes recherches, mes erreurs et mes décisions sans prétendre avoir déjà réussi.'},{id:'education',territory:'esprit',title:'Construire mon éducation',type:'Longue Route',summary:'Philosophie, psychologie, histoire, littérature… une exploration pour toute une vie.',detail:'Je veux construire les connaissances qui me manquent, apprendre à mieux penser et rester curieuse toute ma vie. Je commence par la philosophie et la psychologie.'},{id:'corps-capable',territory:'corps',title:'Corps Capable',type:'Mission',summary:'Apprendre la callisthénie en un an et explorer mes capacités physiques.',detail:'Découvrir ce que mon corps peut apprendre, avec des étapes adaptées, de la régularité et une attention portée à ce que je ressens.'}];
const HIST={jour:'Aujourd’hui',semaine:'Cette semaine',mois:'Ce mois-ci',long:'À long terme'};
const def=()=>({cap:'',capHistory:[],events:[],missions:[],tasks:[],entries:[],notions:[],updatedAt:null}); const clone=(x)=>JSON.parse(JSON.stringify(x));
const safe=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto?.randomUUID?.()||('atlas-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const date=(t)=>{try{return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(t))}catch{return ''}};
const season=()=>{const m=new Date().getMonth();return m<2||m===11?'hiver':m<5?'printemps':m<8?'ete':'automne'};
const seasonName={printemps:'Printemps',ete:'Été',automne:'Automne',hiver:'Hiver'};
const now=()=>new Date().toISOString();
const tinfo=(id)=>TERR.find(t=>t.id===id)||TERR[0];
const DEFAULT_PICTURE={'autonomie':'assets/mission-autonomie.webp','corps':'assets/mission-corps.webp','esprit':'assets/mission-esprit.webp','savoir':'assets/mission-savoir.webp'};
const $=(q,r=document)=>r.querySelector(q); const $$=(q,r=document)=>Array.from(r.querySelectorAll(q));
let st=def(),mode='demo',session=null,view='public',screen='home',focus=null,activeMission=null,territoryFilter='all',missionFilter='all',memoImages={},founderPayload=null,authVariant='login',savePending=Promise.resolve(),toastTime=null,preferPublicAfterLogin=false;
function loadLocal(){try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d&&Array.isArray(d.missions))return {...def(),...d}}catch{}return def()}
function alertUser(message){TOAST.textContent=message;TOAST.classList.add('show');clearTimeout(toastTime);toastTime=setTimeout(()=>TOAST.classList.remove('show'),3600)}
function titleHeader(){return `<a class="brand" href="#" data-action="home"><img src="assets/logo.svg" alt=""><span>ATLAS</span></a>`}
function modal(html,wide=false){focus=document.activeElement;MOD.innerHTML=`<div class="overlay" id="modal-overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Fenêtre ATLAS"><button class="icon-btn dialog-close" type="button" data-action="close" aria-label="Fermer">×</button>${html}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.dialog input, .dialog button, .dialog textarea')?.focus(),15)}
function closeModal(){MOD.innerHTML='';document.body.style.overflow='';try{focus?.focus()}catch{}}
function remember(kind,title,description=''){st.events=Array.isArray(st.events)?st.events:[];st.events.unshift({id:uid(),kind,title,description,created:now()});if(st.events.length>1500)st.events.length=1500}
async function persist(){st.updatedAt=now();if(mode==='demo'){try{localStorage.setItem(KEY,JSON.stringify(st))}catch{alertUser('Stockage local saturé : exporte tes données.')}return}if(!session?.user)return;const data=clone(st),id=session.user.id;savePending=savePending.catch(()=>{}).then(async()=>{const {error}=await cloud.from('atlas_data').upsert({user_id:id,payload:data,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error});try{await savePending}catch(e){console.error('Sauvegarde distante',e);alertUser('Sauvegarde en ligne interrompue. Exporte ton Atlas par précaution.')}}
async function loadCloud(user){const {data,error}=await cloud.from('atlas_data').select('payload').eq('user_id',user.id).maybeSingle();if(error)throw error;st=data?.payload&&Array.isArray(data.payload.missions)?{...def(),...data.payload}:def();mode='cloud';session={user};memoImages={};await refreshPrivatePhotos()}
async function refreshPrivatePhotos(){if(mode!=='cloud')return;for(const entry of st.entries||[]){if(entry.photo?.startsWith('journal/')){const filename=entry.photo.replace(/^journal\//,'');const r=await cloud.storage.from('atlas-private').createSignedUrl(filename,3600);if(!r.error)memoImages[entry.id]=r.data.signedUrl}}}
function showPublic(){view='public';render();window.scrollTo(0,0)}
function showApp(dest='home'){view='app';screen=dest;render();window.scrollTo(0,0)}
const reveal=()=>{if(!('IntersectionObserver'in window)){return}const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}})},{threshold:.06});$$('.reveal').forEach(el=>observer.observe(el))};
function publicHeader(){return `<header class="site-header">${titleHeader()}<nav class="header-links" id="public-nav" aria-label="Navigation principale"><a href="#histoire">Mon histoire</a><a href="#territoires">Les Territoires</a><a href="#missions-publiques">Mes Missions</a><a href="#bibliotheque">Bibliothèque</a><button class="btn slim ghost" data-action="${session?'app':'auth'}">${session?'Mon Atlas':'Se connecter'}</button></nav><button class="icon-btn mobile-menu" aria-label="Ouvrir le menu" data-action="mobile-menu">☰</button></header>`}
function publicMissionList(){const live=founderPayload?.missions||[];const extra=live.filter(x=>!FOUNDER.some(y=>y.id===x.id||y.title===x.title)).map(x=>({id:x.id,title:x.title,territory:x.territory,type:x.type||'Mission',summary:x.description||'Un nouveau chemin en construction.',detail:x.description||'Les avancées seront partagées au fil du temps.'}));return [...FOUNDER,...extra].map(m=>{const t=tinfo(m.territory);const real=live.find(x=>x.id===m.id||x.title===m.title);const n=real?.steps?.length||0,done=real?.steps?.filter(s=>s.done).length||0;return `<article class="publication reveal"><img src="${DEFAULT_PICTURE[m.territory]}" alt="Illustration de ${safe(t.name)}" loading="lazy"><div class="inside"><div class="eyebrow">${t.symbol} ${safe(t.name)} · ${m.type}</div><h3>${safe(m.title)}</h3><p>${safe(m.summary)}</p>${n?`<div class="progress-line"><span style="width:${Math.floor(100*done/n)}%"></span></div><small>${done} étapes rendues publiques sur ${n}</small>`:'<small>Aucune avancée publique déclarée pour le moment</small>'}<div style="margin-top:16px"><button data-action="founder-mission" data-id="${m.id}">Découvrir ce parcours ↗</button></div></div></article>`}).join('')}
function publicPage(){return `${publicHeader()}<main id="main-content"><section class="hero" id="accueil"><div class="container"><div class="intro"><span class="eyebrow" style="color:#f9dbab">✦ ATLAS · LE JEU DES POSSIBLES</span><h1>1 Cap.<em>une infinité de missions.</em></h1><p class="sub">Et si l'on cessait d'attendre pour vraiment vivre ?</p>${founderPayload?.cap?`<p class="small"><strong>Mon Cap :</strong> ${safe(founderPayload.cap)}</p>`:''}<p>Je construis une vie plus libre, curieuse et pleinement vécue. Tu peux suivre mon chemin — ou commencer le tien.</p><div class="hero-actions"><a class="btn light" href="#histoire">Découvrir mon histoire ↗</a><button class="btn ghost" data-action="${session?'app':'auth'}">${session?'Revenir à mon Atlas':'Créer mon Atlas →'}</button></div><span class="script" aria-hidden="true">Le temps d'oser.</span></div></div><div class="hero-stamp">✧<br>EXPLORER<br>APPRENDRE<br>CRÉER<br>VIVRE</div><a class="hero-scroll" href="#histoire">Faire défiler ↓</a></section>
<section class="public-section torn" id="histoire"><div class="container story"><div class="story-art reveal"><img class="main" src="assets/hero-fragment.webp" alt="Terrasse en pierre, carnet ouvert, fleurs et lumière" loading="lazy"><img class="mini" src="assets/sky-fragment.webp" alt="Paysage lumineux au loin" loading="lazy"><div class="story-note">Le courage de commencer.</div></div><div class="story-copy reveal"><div class="section-kicker eyebrow">01 · Mon histoire</div><h2>Bonne partout.<br><em>Excellente nulle part.</em></h2><p>Longtemps, j'ai eu l'impression de savoir faire beaucoup de choses, mais de n'avoir ni passion évidente ni voie toute tracée. J'étais curieuse de tout, sans savoir quelle vie choisir.</p><p>En 2025, j'ai traversé une année particulièrement difficile : les contraintes financières, les études menées avec un travail étudiant, et surtout la perte de ma grand-mère, un pilier de ma vie qui continue de m'inspirer.</p><p>J'ai choisi d'arrêter mes études et de repartir de zéro. Non parce que j'ai toutes les réponses, mais parce que je ne veux plus sacrifier entièrement mon présent à un avenir incertain. Je veux apprendre, me tromper, essayer ce qui m'attire, devenir autonome et être présente dans ma propre vie.</p><p class="line">Je ne cherche pas à accumuler les exploits. Je veux pouvoir regarder ma vie et me dire : j'ai osé la vivre.</p><p>ATLAS est la trace de cette décision. Un Cap — <strong>avoir vraiment vécu, sans regretter ma vie</strong> — et autant de Missions qu'il faudra pour la construire.</p></div></div></section>
<section class="public-section alt territory-section" id="territoires"><div class="container"><div class="section-kicker eyebrow" style="justify-content:center">02 · Les fondations</div><h2>Quatre Territoires.<br><em>Une seule vie.</em></h2><p class="muted">Autant de chemins pour explorer ce qui nous rend plus libres, conscients et capables.</p><div class="territory-grid">${TERR.map(t=>`<article class="territory-card reveal"><img src="${t.image}" alt="${safe(t.name)} : illustration d'atelier" loading="lazy"><h3>${safe(t.name)}</h3><p>${safe(t.question)}</p><div class="foot"><span>${safe(t.symbol)} Explorer</span><button class="icon-btn" data-action="territory-public" data-id="${t.id}" aria-label="Découvrir ${t.name}">↗</button></div></article>`).join('')}</div></div></section>
<section class="public-section" id="missions-publiques"><div class="container"><div class="section-kicker eyebrow">03 · Mon Atlas public</div><h2>Mes Missions <em>en chemin.</em></h2><p class="muted">J'annonce mes nouveaux départs sur Instagram. Ici, je garde les dates, les Étapes, les réflexions et les traces que je choisis de partager. Le silence ne signifie pas qu'une étape est terminée.</p><div class="mission-public">${publicMissionList()}</div><small class="muted">Les projets présentés ne valent pas déclaration de réussite. Les données personnelles des autres utilisateurs ne sont jamais visibles ici.</small></div></section>
<section class="public-section alt" id="bibliotheque"><div class="container public-library"><div class="reveal"><div class="section-kicker eyebrow">04 · L'esprit curieux</div><h2>La Bibliothèque <em>des possibles.</em></h2><p>La philosophie, la psychologie, l'histoire, les livres et les questions qui changent notre manière de voir le monde.</p><p>Une bibliothèque appelée à accueillir des lectures, des Notions et des ressources accessibles. Pour le moment, elle ouvre ses portes progressivement : aucune recommandation experte n'est inventée.</p><button class="btn" data-action="library-public">Entrer dans la Bibliothèque ↗</button></div><img src="assets/esprit.svg" class="reveal" alt="Dessin au trait d'une alcôve et de livres" loading="lazy"></div></section>
<section class="invite" id="commencer"><div class="container"><div><span class="eyebrow" style="color:#dcc394">ET TON HISTOIRE ?</span><h2>Une vie à écrire.<br><em>À ta manière.</em></h2><p>Choisis ton Cap, invente tes Missions, trace tes chemins et conserve leurs souvenirs. Ton Atlas t'appartient : privé par défaut, sans compétition.</p></div><button class="btn light" data-action="${session?'app':'auth'}">${session?'Ouvrir mon Atlas':'Commencer mon Atlas'} ↗</button></div></section></main><footer class="footer"><div class="container"><span>ATLAS · Le jeu des possibles © ${new Date().getFullYear()}</span><span>Un projet de Cloé · Fait pour vivre, pas pour collectionner des cases.</span><button class="link" data-action="legal">Confidentialité & limites</button></div></footer>`}
function seasonCover(){const se=season();return `<section class="seasonal" style="background-image:linear-gradient(0deg,#f7f0e5 0%,rgba(247,240,229,.24) 77%),url('assets/saison-${se}.svg')"><div class="eyebrow">✧ MON CAP · ${seasonName[se]}</div><h1>Mon Cap</h1><p class="cap-quote">« ${safe(st.cap||'Quelle vie ai-je envie de construire ?')} »</p><p class="intro-msg">Un fil à suivre, même quand les plans changent.</p><button class="btn ghost slim" data-action="cap">${st.cap?'Faire évoluer mon Cap':'Écrire mon Cap'} ✎</button></section>`}
const progress=(m)=>{const steps=m.steps||[];return steps.length?Math.round(100*steps.filter(s=>s.done).length/steps.length):0};
function missionTiles(input=st.missions){if(!input.length)return `<div class="empty-state"><div class="script">Tout commence par une envie.</div><h3>Ton prochain chemin reste à inventer.</h3><p>Une idée, une découverte, quelque chose à tenter : tout peut devenir une Mission.</p><button class="btn" data-action="new-mission">Créer ma première Mission →</button></div>`;return `<div class="app-mission-grid">${input.map(m=>{const t=tinfo(m.territory),n=(m.steps||[]).length;return `<article class="app-mission"><img class="banner" src="${DEFAULT_PICTURE[m.territory]}" alt="" loading="lazy"><div class="inside"><span class="eyebrow">${safe(t.name)} · ${safe(m.type||'Mission')}</span><h3>${safe(m.title)}</h3><p class="summary">${safe(m.description||'Une histoire encore à écrire.')}</p><div class="progress-line"><span style="width:${progress(m)}%"></span></div><div class="bottom"><small>${n?(m.steps.filter(x=>x.done).length+' / '+n+' Étapes'):'Étapes à créer'}</small><button class="icon-btn" data-action="mission" data-id="${m.id}" aria-label="Ouvrir ${safe(m.title)}">↗</button></div></div></article>`}).join('')}</div>`}
function horizonCards(){return `<div class="horizon-grid">${Object.entries(HIST).map(([k,label])=>{const tasks=st.tasks.filter(t=>t.horizon===k);return `<div class="horizon-panel"><h3>${k==='jour'?'☼':k==='semaine'?'❧':k==='mois'?'☽':'✧'} ${label}</h3>${tasks.length?tasks.map(t=>`<label class="todo ${t.done?'done':''}"><input type="checkbox" data-check-task="${t.id}" ${t.done?'checked':''}><span class="task-text">${safe(t.title)}</span><button class="link" style="font-size:.7rem" type="button" data-action="remove-task" data-id="${t.id}" aria-label="Supprimer cette action">×</button></label>`).join(''):'<p class="small muted">Aucune action prévue.</p>'}<button class="link small" data-action="new-task" data-horizon="${k}">+ Ajouter</button></div>`}).join('')}</div>`}
function appHeader(){return `<header class="app-header">${titleHeader()}<button class="user-pill" data-action="account"><span class="user-dot" aria-hidden="true"></span><span>${mode==='demo'?'Mode découverte':safe(session?.user?.user_metadata?.username||session?.user?.email?.split('@')[0]||'Mon compte')}</span> <span aria-hidden="true">⌄</span></button></header>`}
function appNav(){return `<nav class="app-bottom" aria-label="Navigation de Mon Atlas">${[{id:'home',name:'Mon Atlas',icon:'✧'},{id:'territories',name:'Territoires',icon:'❧'},{id:'missions',name:'Missions',icon:'☑'},{id:'carnet',name:'Carnet',icon:'▤'}].map(n=>`<button type="button" data-action="tab" data-id="${n.id}" class="${(screen===n.id||(screen==='mission'&&n.id==='missions'))?'active':''}"><span class="nav-icon">${n.icon}</span>${n.name}</button>`).join('')}</nav>`}
function appHome(){return `${seasonCover()}<section class="app-section"><div class="heading-row"><h2>Mes quatre Territoires</h2><span class="small-season">${seasonName[season()]} ✳</span></div><div class="mini-territories">${TERR.map(t=>`<button class="territory-tile" data-action="filter-territory" data-id="${t.id}"><img src="${t.image}" alt=""><strong>${safe(t.name)}</strong><small>${st.missions.filter(m=>m.territory===t.id).length} Mission(s)</small></button>`).join('')}</div></section><section class="app-section"><div class="heading-row"><h2>Mes Missions en cours</h2><button class="link" data-action="new-mission">+ Créer</button></div>${missionTiles(st.missions.filter(m=>m.status!=='archived').slice(0,6))}</section><section class="app-section"><div class="heading-row"><h2>Mes prochains pas</h2><span class="eyebrow">À mon rythme</span></div>${horizonCards()}</section><section class="app-section"><div class="note-banner"><div><span class="eyebrow" style="color:#d1b18b">MES TRACES</span><h3>Mon Carnet de progression</h3><p>Un pas, un doute, une joie, une expérience : ce que tu vis mérite aussi d'être conservé.</p></div><button class="btn light" data-action="new-entry">Écrire une trace ↗</button></div></section><section class="app-section"><div class="heading-row"><h2>Ce que j'apprends</h2><button class="link" data-action="new-notion">+ Une Notion</button></div>${st.notions.length?`<div class="book-grid">${st.notions.slice(-2).reverse().map(n=>`<article class="book-item"><div class="eyebrow">${safe(n.kind)}</div><h4>${safe(n.title)}</h4><p>${safe(n.text)}</p></article>`).join('')}</div>`:'<p class="muted">Ta bibliothèque personnelle accueillera tes lectures, tes idées et les compétences que tu construis.</p>'}</section>`}
function appTerritories(){return `<div class="app-content"><div class="eyebrow">MA CARTE PERSONNELLE</div><h2>Mes quatre Territoires.</h2><p>Une direction commune, des chemins différents. Tu peux revenir, changer de route, ou simplement contempler.</p><div class="territory-grid">${TERR.map(t=>`<article class="territory-card"><img src="${t.image}" alt="" loading="lazy"><h3>${safe(t.name)}</h3><p>${safe(t.question)}</p><div class="foot"><span>${st.missions.filter(m=>m.territory===t.id).length} chemin(s)</span><button class="icon-btn" data-action="filter-territory" data-id="${t.id}" aria-label="Voir mes Missions en ${safe(t.name)}">→</button></div></article>`).join('')}</div></div>`}
function appMissions(){const filter=missionFilter==='all'?st.missions:st.missions.filter(m=>m.territory===missionFilter);return `<div class="app-content"><div class="eyebrow">MES POSSIBLES</div><h2>Mes Missions.</h2><p class="muted">Des envies aux aventures, des idées aux premières Étapes. Rien n'est une course.</p><div class="heading-row"><div class="filters"><button data-action="mission-filter" data-id="all" class="${missionFilter==='all'?'active':''}">Toutes</button>${TERR.map(t=>`<button data-action="mission-filter" data-id="${t.id}" class="${missionFilter===t.id?'active':''}">${safe(t.name)}</button>`).join('')}</div><button class="btn slim" data-action="new-mission">+ Créer</button></div>${missionTiles(filter)}</div>`}
function appCarnet(){const arr=[...st.entries].sort((a,b)=>new Date(b.created)-new Date(a.created));return `<div class="app-content"><div class="eyebrow">MA MÉMOIRE VIVANTE</div><h2>Mon Carnet.</h2><p class="muted">Un endroit pour se souvenir des décisions, des erreurs, des doutes, des expériences et des belles surprises.</p><button class="btn" data-action="new-entry">+ Écrire une trace</button><div class="journal-list" style="margin-top:25px">${arr.length?arr.map(e=>{const m=st.missions.find(m=>m.id===e.missionId);const img=memoImages[e.id]||(e.photo?.startsWith('data:')?e.photo:null);return `<article class="entry"><div class="meta">${date(e.created)} · ${safe(e.kind||'Souvenir')} ${m?' · '+safe(m.title):''}</div><p class="content">${safe(e.text)}</p>${img?`<img class="entry-photo" src="${img}" alt="Photographie du Carnet">`:''}<div class="actions"><button class="link" data-action="delete-entry" data-id="${e.id}">Supprimer</button>${mode==='cloud'&&isFounder()?`<label class="small"><input type="checkbox" data-public-entry="${e.id}" ${e.isPublic?'checked':''}> Rendre cette trace publique (texte seulement)</label>`:''}</div></article>`}).join(''):'<div class="empty-state"><h3>Les premières pages sont à écrire.</h3><p>Un petit moment mérite aussi une place dans ton histoire.</p></div>'}</div><section class="app-section"><div class="heading-row"><h3>Ma bibliothèque de notions</h3><button class="link" data-action="new-notion">+ Ajouter</button></div><div class="book-grid">${st.notions.map(n=>`<article class="book-item"><div class="eyebrow">${safe(n.kind)}</div><h4>${safe(n.title)}</h4><p>${safe(n.text)}</p><button class="link" data-action="delete-notion" data-id="${n.id}">Supprimer</button></article>`).join('')||'<p class="muted">Les découvertes conservées apparaîtront ici.</p>'}</div></section><section class="app-section"><div class="heading-row"><h3>La mémoire du chemin</h3><span class="eyebrow">Au fil du temps</span></div>${(st.events||[]).length?`<div class="journal-list">${st.events.slice(0,25).map(ev=>`<article class="entry"><div class="meta">${date(ev.created)} · ${safe(ev.kind)}</div><strong>${safe(ev.title)}</strong>${ev.description?`<p class="small muted">${safe(ev.description)}</p>`:''}</article>`).join('')}</div>`:'<p class="muted">Les grands moments de ta progression s’inscriront ici au fur et à mesure.</p>'}${(st.capHistory||[]).length?`<p class="small muted">Anciens Caps conservés : ${st.capHistory.map(c=>safe(c.cap)).join(' · ')}</p>`:''}</section></div>`}
function appMission(){const m=st.missions.find(m=>m.id===activeMission);if(!m)return appMissions();const t=tinfo(m.territory),steps=m.steps||[],done=steps.filter(s=>s.done).length,all=steps.length&&done===steps.length;const journal=st.entries.filter(e=>e.missionId===m.id);return `<div class="app-content"><button class="link back" data-action="tab" data-id="missions">← Toutes mes Missions</button><div class="territory-subhead"><img src="${t.image}" alt=""><div><div class="eyebrow">${t.symbol} ${safe(t.name)} · ${safe(m.type||'Mission')}</div><h2>${safe(m.title)}</h2><p class="muted">${safe(m.description||'Une expérience à construire.')}</p></div></div><div class="panel"><div class="heading-row"><span class="eyebrow">MON AVANCÉE</span><span>${done} / ${steps.length} Étapes</span></div><div class="progress-line"><span style="width:${progress(m)}%"></span></div><p class="small muted">Les Étapes cochées restent conservées, même si tu changes de route.</p><div class="actions" style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn slim ghost" data-action="edit-mission" data-id="${m.id}">Modifier</button><button class="btn slim plain" data-action="new-step" data-id="${m.id}">+ Ajouter une Étape</button><button class="btn slim plain" data-action="archive-mission" data-id="${m.id}">${m.status==='archived'?'Réactiver':'Archiver'}</button></div>${mode==='cloud'&&isFounder()?`<label class="small" style="display:block;margin-top:15px"><input type="checkbox" data-public-mission="${m.id}" ${m.isPublic?'checked':''}> Publier cette Mission et ses Étapes sur mon Atlas public</label>`:''}</div><div class="heading-row"><h3>Le chemin parcouru</h3><span class="eyebrow">${all?'Chemin accompli':'En route'}</span></div><div class="mission-map">${steps.map((s,i)=>{const unlocked=i===0||steps.slice(0,i).every(x=>x.done);return `<article class="step-node ${s.done?'done':unlocked?'current':'locked'}"><div class="step-seal">${s.done?'✓':unlocked?'✦':'♧'}</div><div class="step-content"><div class="step-meta">ÉTAPE ${i+1} ${s.done?'· ACCOMPLIE':unlocked?'· OUVERTE':'· À VENIR'}</div><h3>${safe(s.title)}</h3>${s.details?`<p>${safe(s.details)}</p>`:''}<div class="actions">${s.done?`<label class="small"><input type="checkbox" checked data-check-step="${s.id}"> Accomplie</label>`:unlocked?`<button class="btn slim" data-action="finish-step" data-id="${s.id}">Marquer comme accomplie ✧</button>`:'<span class="small muted">🔒 Elle s’ouvrira avec le chemin précédent</span>'}<button class="link small" data-action="edit-step" data-id="${s.id}">Modifier</button></div></div></article>`}).join('')||'<div class="empty-state"><h3>La carte attend son premier repère.</h3><button class="btn" data-action="new-step" data-id="'+m.id+'">Ajouter une Étape ✦</button></div>'}</div><div class="panel"><h3>Mes notes de Mission</h3><p>Les essais, les doutes et les enseignements forment aussi le chemin.</p><p class="small muted">${journal.length} trace(s) conservée(s) dans le Carnet.</p><button class="btn ghost" data-action="new-entry" data-id="${m.id}">Écrire ce que j'ai vécu ↗</button></div>${all?`<section class="recap-hero"><div class="eyebrow">TON CHEMIN, TON HISTOIRE</div><h2>Cette Mission a été vécue.</h2><p class="script">Ce que tu as tenté compte.</p><p>Tu peux être fière d'avoir avancé, avec tes hésitations et tes découvertes. Ce qui importe n'est pas la perfection de ton parcours mais la vie que tu as mise dedans.</p><button class="btn" data-action="recap" data-id="${m.id}">Ouvrir mon récapitulatif ↗</button></section>`:''}</div>`}
function appBody(){if(screen==='home')return appHome();if(screen==='territories')return appTerritories();if(screen==='missions')return appMissions();if(screen==='mission')return appMission();if(screen==='carnet')return appCarnet();return appHome()}
function render(){document.title=view==='public'?'ATLAS — 1 Cap, une infinité de Missions':'Mon Atlas — Le jeu des possibles';ROOT.innerHTML=view==='public'?publicPage():`<div class="app-shell" data-season="${season()}">${appHeader()}<main class="app-main" id="main-content">${appBody()}</main>${appNav()}</div>`;reveal()}
function isFounder(){return mode==='cloud'&&session?.user?.id&&CONFIG.founderUserId&&session.user.id===CONFIG.founderUserId}
function authDialog(variant='login'){authVariant=variant;if(!configured){return modal(`<span class="eyebrow">PRÉVERSION LOCALE</span><h2>Ton Atlas t'attend.</h2><p>La création de comptes nécessite encore l'activation de Supabase. Tu peux déjà découvrir l'espace personnel et enregistrer un Atlas sur cet appareil, sans mot de passe.</p><div class="notice">Cette démonstration n'est pas un compte privé sécurisé. Ne saisis pas d'informations sensibles.</div><button class="btn" data-action="start-demo">Essayer Mon Atlas →</button><p class="small muted">Le site public reste consultable sans inscription.</p>`)}
const isRegister=variant==='register',isRecover=variant==='recover';modal(`<span class="eyebrow">MON ESPACE PERSONNEL</span><h2>${isRegister?'Commencer mon Atlas':isRecover?'Retrouver mon accès':'Se retrouver.'}</h2><p>${isRegister?'Un espace personnel pour construire et conserver tes propres chemins.':isRecover?'Reçois un lien de réinitialisation à l’adresse associée à ton compte.':'Retrouve ton Cap, tes Missions et tes souvenirs là où tu les avais laissés.'}</p><form id="auth-form"><input type="hidden" name="variant" value="${variant}">${isRegister?`<label for="authUsername">Nom d’utilisateur public (3 à 24 caractères)</label><input id="authUsername" name="username" autocomplete="username" required pattern="[A-Za-z0-9_-]{3,24}" maxlength="24" placeholder="ton_pseudo">`:''}<label for="authEmail">Adresse e-mail</label><input id="authEmail" name="email" type="email" autocomplete="email" required placeholder="tonadresse@exemple.fr">${!isRecover?`<label for="authPassword">Mot de passe (10 caractères minimum)</label><input id="authPassword" name="password" type="password" minlength="10" autocomplete="${isRegister?'new-password':'current-password'}" required>`:''}<div class="form-actions"><button class="btn" type="submit">${isRecover?'Envoyer le lien':isRegister?'Créer mon compte':'Se connecter'} →</button></div></form><div class="auth-switch"><button class="link" data-action="auth-variant" data-id="${isRegister?'login':'register'}">${isRegister?'J’ai déjà un compte':'Créer un compte'}</button> · <button class="link" data-action="auth-variant" data-id="${isRecover?'login':'recover'}">${isRecover?'Se connecter':'Mot de passe oublié ?'}</button></div><p class="auth-help">Le nom d’utilisateur sert à personnaliser ton espace. La connexion utilise l’adresse e-mail et le mot de passe, pour permettre une récupération sécurisée du compte.</p>`)}
function passwordDialog(){modal(`<span class="eyebrow">SÉCURISER MON COMPTE</span><h2>Choisir un nouveau mot de passe.</h2><form id="password-form"><label for="newPassword">Nouveau mot de passe (10 caractères minimum)</label><input id="newPassword" name="password" type="password" autocomplete="new-password" required minlength="10"><div class="form-actions"><button class="btn" type="submit">Enregistrer ce mot de passe</button></div></form>`)}
function capDialog(){modal(`<span class="eyebrow">MA BOUSSOLE</span><h2>Quelle vie as-tu envie de construire ?</h2><p>Il n'y a ni bonne réponse, ni date limite. Ton Cap peut changer quand tu changes.</p><form id="cap-form"><label for="capField">Mon Cap</label><textarea id="capField" maxlength="1300" name="cap" required placeholder="Une vie plus libre, curieuse et pleine d'expériences…">${safe(st.cap)}</textarea><div class="form-actions"><button class="btn" type="submit">Conserver mon Cap ✧</button></div></form>`)}
function missionDialog(id=null,territory='autonomie'){const m=st.missions.find(x=>x.id===id);modal(`<span class="eyebrow">MES CHEMINS</span><h2>${m?'Faire évoluer ma Mission.':'Un chemin à inventer.'}</h2><p>Choisis une expérience, une envie ou une capacité à développer. Ses Étapes pourront évoluer avec toi.</p><form id="mission-form"><input type="hidden" name="id" value="${safe(m?.id||'')}"><label for="mTitle">Nom de ma Mission</label><input id="mTitle" maxlength="140" name="title" required value="${safe(m?.title||'')}" placeholder="Ex. Apprendre la callisthénie en 1 an"><label for="mTerr">Territoire</label><select id="mTerr" name="territory">${TERR.map(t=>`<option value="${t.id}" ${(m?.territory||territory)===t.id?'selected':''}>${t.name}</option>`).join('')}</select><label for="mType">Nature du chemin</label><select id="mType" name="type"><option ${m?.type==='Mission'?'selected':''}>Mission</option><option ${m?.type==='Expédition'?'selected':''}>Expédition</option><option ${m?.type==='Longue Route'?'selected':''}>Longue Route</option></select><label for="mDescription">Pourquoi est-ce important ?</label><textarea id="mDescription" name="description" maxlength="2000" placeholder="Ce que j'aimerais vivre, apprendre ou construire…">${safe(m?.description||'')}</textarea><div class="form-actions"><button class="btn" type="submit">Enregistrer ma Mission ✧</button>${m?`<button class="btn plain" type="button" data-action="delete-mission" data-id="${m.id}">Supprimer</button>`:''}</div></form>`)}
function stepDialog(missionId,stepId){const m=st.missions.find(x=>x.id===missionId);if(!m)return;const s=(m.steps||[]).find(s=>s.id===stepId);modal(`<span class="eyebrow">${safe(m.title)}</span><h2>${s?'Modifier un repère':'Planter un repère sur la carte.'}</h2><p>Une Étape est une promesse faite à toi-même, pas une preuve à fournir aux autres.</p><form id="step-form"><input type="hidden" name="missionId" value="${m.id}"><input type="hidden" name="id" value="${safe(s?.id||'')}"><label for="stepTitle">Étape</label><input id="stepTitle" name="title" required maxlength="160" value="${safe(s?.title||'')}" placeholder="Ex. Apprendre les bases"><label for="stepDetails">Notes ou critères personnels</label><textarea name="details" id="stepDetails" maxlength="2500" placeholder="Comment saurai-je que j'ai essayé ou avancé ?">${safe(s?.details||'')}</textarea><div class="form-actions"><button class="btn" type="submit">${s?'Conserver les changements':'Ajouter au chemin'} →</button>${s?`<button type="button" class="btn plain" data-action="delete-step" data-id="${s.id}" data-mid="${m.id}">Supprimer</button>`:''}</div></form>`)}
function taskDialog(horizon='jour'){modal(`<span class="eyebrow">MES PETITS PAS</span><h2>Une action à garder en vue.</h2><p>Une aide pour revenir à ce qui compte, sans date limite imposée ni série à maintenir.</p><form id="task-form"><label for="taskTitle">Mon action</label><input required id="taskTitle" name="title" maxlength="180" placeholder="Ex. Lire 10 pages"><label for="taskHorizon">Quand voudrais-tu y penser ?</label><select id="taskHorizon" name="horizon">${Object.entries(HIST).map(([id,label])=>`<option value="${id}" ${id===horizon?'selected':''}>${label}</option>`).join('')}</select><label for="taskMission">Mission liée (facultatif)</label><select id="taskMission" name="missionId"><option value="">Une action libre</option>${st.missions.map(m=>`<option value="${m.id}">${safe(m.title)}</option>`).join('')}</select><div class="form-actions"><button class="btn" type="submit">Ajouter cette action ✧</button></div></form>`)}
function entryDialog(mid=''){modal(`<span class="eyebrow">MON CARNET DE VIE</span><h2>Qu'as-tu envie de garder ?</h2><p>Une avancée, une erreur, un souvenir, une réflexion : la valeur d'une vie ne se résume pas aux réussites.</p><form id="entry-form"><label for="entryKind">Nature de la trace</label><select name="kind" id="entryKind">${['Avancée','Réflexion','Apprentissage','Décision','Erreur','Doute','Souvenir','Victoire'].map(k=>`<option>${k}</option>`).join('')}</select><label for="entryMission">Associer à une Mission (facultatif)</label><select name="missionId" id="entryMission"><option value="">Un moment de vie</option>${st.missions.map(m=>`<option value="${m.id}" ${m.id===mid?'selected':''}>${safe(m.title)}</option>`).join('')}</select><label for="entryText">Ton récit</label><textarea id="entryText" name="text" required maxlength="8000" placeholder="Aujourd'hui, j'ai appris…"></textarea><label for="entryPhoto">Une photographie (facultative, 3 Mo maximum)</label><input id="entryPhoto" name="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="photo-help"><p id="photo-help" class="small muted">En ligne, les images sont stockées dans un espace privé. En démonstration, elles sont compressées et conservées uniquement sur ton appareil.</p><div class="form-actions"><button class="btn" type="submit">Conserver cette trace ✧</button></div></form>`)}
function notionDialog(){modal(`<span class="eyebrow">MA BIBLIOTHÈQUE PERSONNELLE</span><h2>Ce que j'apprends.</h2><p>Une idée que tu comprends, une lecture marquante, une compétence qui grandit.</p><form id="notion-form"><label for="notionType">Nature</label><select name="kind" id="notionType"><option>Notion</option><option>Lecture</option><option>Compétence</option><option>Question</option></select><label for="notionTitle">Titre</label><input required name="title" maxlength="170" id="notionTitle"><label for="notionText">Ce que je retiens</label><textarea required name="text" maxlength="4000" id="notionText"></textarea><div class="form-actions"><button class="btn">Conserver dans ma Bibliothèque ✧</button></div></form>`)}
function accountDialog(){modal(`<span class="eyebrow">MON ESPACE</span><h2>${mode==='demo'?'Découverte locale':'Ton espace personnel.'}</h2><p>${mode==='demo'?'Cet Atlas est seulement conservé dans ce navigateur. Pour retrouver tes données entre plusieurs appareils, il faudra créer un compte sécurisé.':'Connectée avec '+safe(session?.user?.email||'ton compte')+'. Tes changements sont sauvegardés dans ton compte lorsque la synchronisation réussit.'}</p><div class="notice">Tu peux exporter une copie JSON de tes données. Conserve-la dans un endroit privé.</div><div class="form-actions"><button class="btn" data-action="export">Exporter mon Atlas ↓</button>${mode==='demo'&&configured?'<button class="btn ghost" data-action="auth">Créer mon compte</button>':''}${isFounder()?'<button class="btn ghost" data-action="publish">Mettre à jour mon Atlas public</button>':''}<button class="btn plain" data-action="home">Site public ↗</button>${mode==='cloud'?'<button class="btn plain" data-action="logout">Se déconnecter</button>':''}</div><p class="small muted">Pour la sécurité de tes souvenirs : évite de publier des informations intimes. Les entrées de Carnet sont privées par défaut.</p>`)}
function founderMissionDialog(id){const m=FOUNDER.find(x=>x.id===id);if(!m)return;const live=founderPayload?.missions?.find(x=>x.id===m.id||x.title===m.title);const entries=(founderPayload?.entries||[]).filter(e=>live?e.missionId===live.id:false);const t=tinfo(m.territory);modal(`<div class="eyebrow">MON ATLAS PUBLIC · ${safe(t.name)}</div><h2>${safe(m.title)}</h2><img src="${t.image}" style="width:100%;height:200px;object-fit:cover;border-radius:10px;margin:10px 0" alt=""><p><strong>${safe(m.summary)}</strong></p><p>${safe(m.detail)}</p>${live?.steps?.length?`<h3>Le chemin rendu public</h3><div class="mission-map">${live.steps.map((s,i)=>`<div class="step-node ${s.done?'done':'locked'}"><span class="step-seal">${s.done?'✓':'✧'}</span><div class="step-content"><small>Étape ${i+1}</small><h3>${safe(s.title)}</h3></div></div>`).join('')}</div>`:'<div class="notice">Mes avancées détaillées seront ajoutées lorsque je choisirai de les rendre publiques. Aucun accomplissement n’est supposé.</div>'}${entries.length?`<h3>Fragments du Carnet public</h3>${entries.map(e=>`<p><small>${date(e.created)}</small><br>${safe(e.text)}</p>`).join('')}`:''}`,true)}
function territoryDialog(id){const t=tinfo(id);modal(`<div class="eyebrow">UN TERRITOIRE DE VIE</div><h2>${safe(t.name)}</h2><img src="${t.image}" style="width:100%;max-height:240px;object-fit:cover;border-radius:10px;margin-bottom:15px"><p><strong>${safe(t.question)}</strong></p><p>${safe(t.desc)}</p>${FOUNDER.filter(m=>m.territory===id).map(m=>`<button class="btn ghost" data-action="founder-mission" data-id="${m.id}">Voir « ${safe(m.title)} » ↗</button>`).join('')||'<p class="muted">De nouvelles Missions viendront enrichir ce Territoire.</p>'}`)}
function libraryDialog(){modal(`<div class="eyebrow">UNE BIBLIOTHÈQUE EN CONSTRUCTION</div><h2>Apprendre pour mieux vivre.</h2><img src="assets/bibliotheque.svg" style="width:100%;max-height:245px;object-fit:cover;margin:15px 0" alt="Illustration d'une bibliothèque"><p>Cette Bibliothèque rassemblera des réflexions, des lectures et des ressources documentées en philosophie, psychologie, culture et autonomie.</p><p>Les contenus arriveront progressivement. Je préfère transmettre des apprentissages vérifiés plutôt que remplir artificiellement des étagères.</p>`)}
function legalDialog(){modal(`<span class="eyebrow">CONFIDENTIALITÉ & LIMITE DE LA PRÉVERSION</span><h2>Ton histoire t'appartient.</h2><p>Les comptes et les fichiers privés nécessitent un projet Supabase configuré et des règles d'accès en base de données. Sans configuration, ATLAS fonctionne uniquement en démonstration locale.</p><p>Le partage public d'éléments du compte fondateur demande une action volontaire. Un carnet personnel ne devient jamais public automatiquement.</p><p>Avant un lancement public réel, il faudra publier les mentions légales, une politique de confidentialité complète, un contact et un processus de suppression et d’export des données.</p><p>Les guides futurs sur la santé et les finances devront reposer sur des sources adaptées ; ATLAS ne remplace pas un professionnel.</p>`)}
function recapDialog(m){const steps=m.steps||[],entries=st.entries.filter(e=>e.missionId===m.id);modal(`<div class="eyebrow">UNE MISSION, UNE HISTOIRE</div><h2>${safe(m.title)}</h2><p class="script">Tu as fait de ce possible une expérience.</p><p>Tu as avancé avec les ressources, les hésitations et les découvertes du moment. Cela compte. Tu peux être fière de ce que tu as tenté, indépendamment de la perfection du résultat.</p><p><strong>${steps.filter(s=>s.done).length} Étapes franchies</strong> · ${entries.length} traces de Carnet · commencée le ${date(m.created)}</p><h3>Ce que je retiens de cette aventure</h3><form id="recap-form"><input type="hidden" name="id" value="${m.id}"><label for="reflection">Mon ressenti, mes erreurs, mes souvenirs et ce que j'ai appris</label><textarea id="reflection" name="reflection" rows="6" maxlength="6000" placeholder="Maintenant que je regarde le chemin…">${safe(m.reflection||'')}</textarea><div class="form-actions"><button class="btn" type="submit">Conserver ce souvenir ✧</button></div></form>`,true)}
function stamp(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){alertUser('Une Étape de plus dans ton histoire ✧');return}const el=document.createElement('div');el.className='celebration';el.textContent='Un pas de plus';document.body.append(el);setTimeout(()=>el.remove(),1100)}
function askDelete(what,id,extra=''){modal(`<div class="eyebrow">UN CHOIX IMPORTANT</div><h2>Supprimer cet élément ?</h2><p>Il ne sera plus présent dans ton Atlas. Si tu veux conserver le souvenir d'une Mission, préfère l'archivage.</p><div class="form-actions"><button class="btn plain" data-action="close">Annuler</button><button class="btn" data-action="confirm-delete" data-type="${safe(what)}" data-id="${safe(id)}" data-extra="${safe(extra)}">Oui, supprimer</button></div>`)}
async function imageToData(file){if(!file)return null;if(file.size>3*1024*1024)throw Error('Image trop volumineuse (3 Mo maximum).');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Format image non accepté.');const img=await createImageBitmap(file);const max=1150,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close?.();return canvas.toDataURL('image/jpeg',.7)}
async function addEntry(d,file){const entry={id:uid(),text:String(d.text||'').trim(),kind:d.kind,missionId:d.missionId||'',created:now(),photo:null,isPublic:false};if(file?.size){const data=await imageToData(file);if(mode==='demo'){entry.photo=data}else{const raw=await(await fetch(data)).blob(),path=`${session.user.id}/${entry.id}.jpg`;const r=await cloud.storage.from('atlas-private').upload(path,raw,{contentType:'image/jpeg',upsert:false});if(r.error)throw r.error;entry.photo='journal/'+path;const url=await cloud.storage.from('atlas-private').createSignedUrl(path,3600);if(!url.error)memoImages[entry.id]=url.data.signedUrl}}st.entries.push(entry);remember('Carnet','Une trace de vie a été enregistrée',entry.kind);await persist();return entry}
async function publishFounder(){if(!isFounder())return;const payload={cap:st.cap||'Avoir vraiment vécu et ne pas regretter ma vie.',updatedAt:now(),missions:st.missions.filter(m=>m.isPublic).map(m=>({id:m.id,title:m.title,territory:m.territory,type:m.type,description:m.description,steps:m.steps.map(s=>({id:s.id,title:s.title,done:!!s.done}))})),entries:st.entries.filter(e=>e.isPublic).map(e=>({id:e.id,kind:e.kind,text:e.text,created:e.created,missionId:e.missionId}))};const {error}=await cloud.from('public_pages').upsert({user_id:session.user.id,is_published:true,payload,updated_at:now()},{onConflict:'user_id'});if(error)throw error;founderPayload=payload;alertUser('Tes éléments sélectionnés sont maintenant publics.');closeModal()}
async function syncFounder(){if(!configured||!CONFIG.founderUserId)return;const {data,error}=await cloud.from('public_pages').select('payload').eq('user_id',CONFIG.founderUserId).eq('is_published',true).maybeSingle();if(!error&&data)founderPayload=data.payload}
async function logout(){if(mode!=='cloud')return;await cloud.auth.signOut();session=null;mode='demo';st=loadLocal();closeModal();showPublic();alertUser('Déconnexion effectuée.')}
function downloadJSON(){const obj={format:'atlas-v1',exportedAt:now(),data:st};const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mon-atlas-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);alertUser('Une copie de ton Atlas a été exportée.')}
// Every visible action uses delegation: DOM may be refreshed after a change.
document.addEventListener('click',async e=>{const el=e.target.closest('button[data-action],a[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(el.tagName==='A')e.preventDefault();try{
if(a==='close')closeModal();else if(a==='home'){closeModal();showPublic()}else if(a==='mobile-menu')$('#public-nav')?.classList.toggle('show');else if(a==='auth')authDialog();else if(a==='auth-variant')authDialog(id);else if(a==='start-demo'){st=loadLocal();mode='demo';closeModal();showApp()}else if(a==='app'){if(mode==='cloud'&&session){closeModal();showApp()}else if(!configured){st=loadLocal();showApp()}else authDialog()}
else if(a==='tab'){screen=id;render();window.scrollTo(0,0)}else if(a==='cap')capDialog();else if(a==='new-mission')missionDialog(null,missionFilter==='all'?'autonomie':missionFilter);else if(a==='filter-territory'){missionFilter=id;screen='missions';render();window.scrollTo(0,0)}else if(a==='mission-filter'){missionFilter=id;render()}else if(a==='mission'){activeMission=id;screen='mission';render();window.scrollTo(0,0)}else if(a==='edit-mission')missionDialog(id);else if(a==='new-step')stepDialog(id);else if(a==='edit-step')stepDialog(activeMission,id);else if(a==='new-task')taskDialog(el.dataset.horizon||'jour');else if(a==='new-entry')entryDialog(id||'');else if(a==='new-notion')notionDialog();else if(a==='account')accountDialog();else if(a==='founder-mission')founderMissionDialog(id);else if(a==='territory-public')territoryDialog(id);else if(a==='library-public')libraryDialog();else if(a==='legal')legalDialog();else if(a==='export')downloadJSON();else if(a==='publish')await publishFounder();else if(a==='logout')await logout();else if(a==='recap')recapDialog(st.missions.find(m=>m.id===id));
else if(a==='finish-step'){const m=st.missions.find(m=>m.id===activeMission),i=m?.steps?.findIndex(s=>s.id===id);if(i<0)return;if(i>0&&!m.steps.slice(0,i).every(x=>x.done))return;m.steps[i].done=true;m.steps[i].doneAt=now();remember('Étape',m.steps[i].title,m.title);if(m.steps.every(s=>s.done)){m.completedAt=now();remember('Mission','Mission accomplie : '+m.title)}await persist();render();stamp()}
else if(a==='archive-mission'){const m=st.missions.find(m=>m.id===id);if(m){m.status=m.status==='archived'?'active':'archived';await persist();render();alertUser('Le statut de la Mission a évolué.')}}
else if(a==='remove-task')askDelete('task',id);else if(a==='delete-mission')askDelete('mission',id);else if(a==='delete-step')askDelete('step',id,el.dataset.mid);else if(a==='delete-entry')askDelete('entry',id);else if(a==='delete-notion')askDelete('notion',id);
else if(a==='confirm-delete'){const t=el.dataset.type;if(t==='mission'){st.missions=st.missions.filter(m=>m.id!==id);st.tasks.forEach(t=>{if(t.missionId===id)t.missionId=''})}if(t==='step'){const m=st.missions.find(m=>m.id===el.dataset.extra);if(m)m.steps=m.steps.filter(s=>s.id!==id)}if(t==='task')st.tasks=st.tasks.filter(t=>t.id!==id);if(t==='entry'){const ent=st.entries.find(e=>e.id===id);if(mode==='cloud'&&ent?.photo?.startsWith('journal/'))await cloud.storage.from('atlas-private').remove([ent.photo.replace('journal/','')]);st.entries=st.entries.filter(e=>e.id!==id)}if(t==='notion')st.notions=st.notions.filter(n=>n.id!==id);await persist();closeModal();if(!st.missions.find(m=>m.id===activeMission))screen='missions';render();alertUser('Élément supprimé.')}
}catch(err){console.error(err);alertUser('Action non terminée : '+(err.message||'essaie à nouveau.'))}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.checkTask){const t=st.tasks.find(x=>x.id===el.dataset.checkTask);if(!t)return;t.done=el.checked;t.doneAt=el.checked?now():null;await persist();render();if(t.done)stamp()}else if(el.dataset.checkStep){const m=st.missions.find(m=>m.id===activeMission),i=m?.steps.findIndex(s=>s.id===el.dataset.checkStep);if(i<0)return;m.steps[i].done=el.checked;m.steps[i].doneAt=el.checked?now():null;if(el.checked)remember('Étape',m.steps[i].title,m.title);if(m.steps.length&&m.steps.every(s=>s.done)&&!m.completedAt){m.completedAt=now();remember('Mission','Mission accomplie : '+m.title)}await persist();render();if(el.checked)stamp()}else if(el.dataset.publicMission&&isFounder()){const m=st.missions.find(m=>m.id===el.dataset.publicMission);if(m)m.isPublic=el.checked;await persist();alertUser('Sélection enregistrée. Publie ensuite depuis ton compte.')}else if(el.dataset.publicEntry&&isFounder()){const v=st.entries.find(x=>x.id===el.dataset.publicEntry);if(v)v.isPublic=el.checked;await persist();alertUser('Sélection enregistrée. Publie ensuite depuis ton compte.')}}catch(err){alertUser('Impossible de sauvegarder ce changement.')}});
document.addEventListener('submit',async e=>{const f=e.target;const fid=f.getAttribute('id');if(!['cap-form','mission-form','step-form','task-form','entry-form','notion-form','recap-form','auth-form','password-form'].includes(fid))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{if(fid==='cap-form'){if(!d.cap.trim())throw Error('Le Cap ne peut pas être vide.');const next=d.cap.trim();if(st.cap&&st.cap!==next){st.capHistory=Array.isArray(st.capHistory)?st.capHistory:[];st.capHistory.push({cap:st.cap,endedAt:now()});remember('Cap','Le Cap a évolué')}st.cap=next;await persist();closeModal();render();alertUser('Ton Cap est conservé ✧')}
else if(fid==='mission-form'){const old=st.missions.find(m=>m.id===d.id);if(old){Object.assign(old,{title:d.title.trim(),territory:d.territory,type:d.type,description:d.description.trim()})}else{const m={id:uid(),title:d.title.trim(),territory:d.territory,type:d.type,description:d.description.trim(),steps:[],status:'active',created:now(),reflection:'',isPublic:false};st.missions.push(m);remember('Mission','Nouvelle Mission : '+m.title);activeMission=m.id;screen='mission'}await persist();closeModal();render();alertUser('Mission enregistrée ✧')}
else if(fid==='step-form'){const m=st.missions.find(x=>x.id===d.missionId);if(!m)throw Error('Mission introuvable.');const s=m.steps.find(s=>s.id===d.id);if(s){s.title=d.title.trim();s.details=d.details.trim()}else {m.steps.push({id:uid(),title:d.title.trim(),details:d.details.trim(),done:false,created:now()});remember('Étape','Étape créée : '+d.title.trim(),m.title)};activeMission=m.id;screen='mission';await persist();closeModal();render();alertUser('Ton chemin s’enrichit d’un repère ✧')}
else if(fid==='task-form'){st.tasks.push({id:uid(),title:d.title.trim(),horizon:d.horizon,missionId:d.missionId||'',done:false,created:now()});await persist();closeModal();render();alertUser('Une action à retrouver ✧')}
else if(fid==='entry-form'){const file=$('#entryPhoto')?.files?.[0];await addEntry(d,file);closeModal();screen='carnet';render();alertUser('Ta trace est conservée ✧')}
else if(fid==='notion-form'){st.notions.push({id:uid(),kind:d.kind,title:d.title.trim(),text:d.text.trim(),created:now()});await persist();closeModal();screen='carnet';render();alertUser('Un savoir de plus dans ta Bibliothèque ✧')}
else if(fid==='recap-form'){const m=st.missions.find(x=>x.id===d.id);m.reflection=d.reflection.trim();await persist();closeModal();render();alertUser('Le souvenir de ce chemin est conservé.')}
else if(fid==='password-form'){if(!cloud)throw Error('Service non configuré.');const r=await cloud.auth.updateUser({password:d.password});if(r.error)throw r.error;closeModal();alertUser('Ton nouveau mot de passe est enregistré.')}
else if(fid==='auth-form'){if(!cloud)throw Error('Connexion non configurée.');const email=d.email.trim().toLowerCase();if(d.variant==='register'){const uname=d.username.trim().toLowerCase();if(!/^[a-z0-9_-]{3,24}$/.test(uname))throw Error('Choisis un pseudo de 3 à 24 caractères (lettres, chiffres, _ ou -).');const r=await cloud.auth.signUp({email,password:d.password,options:{data:{username:uname}}});if(r.error)throw r.error;closeModal();if(r.data.session){session=r.data.session;await loadCloud(session.user);showApp();alertUser('Ton Atlas est prêt.')}else alertUser('Vérifie ta boîte e-mail pour confirmer ton compte.')}else if(d.variant==='recover'){const r=await cloud.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(r.error)throw r.error;closeModal();alertUser('Si un compte existe, tu recevras un e-mail de réinitialisation.')}else{const r=await cloud.auth.signInWithPassword({email,password:d.password});if(r.error)throw r.error;session=r.data.session;await loadCloud(session.user);closeModal();showApp();alertUser('Bienvenue dans ton Atlas ✧')}}
}catch(err){console.error('Form error',err);alertUser(err.message||'Un problème a empêché l’enregistrement.')}finally{if(submit?.isConnected)submit.disabled=false}});
MOD.addEventListener('click',e=>{if(e.target.id==='modal-overlay')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
async function init(){st=loadLocal();render();if(configured){try{await syncFounder();const {data,error}=await cloud.auth.getSession();if(error)throw error;if(data?.session){session=data.session;await loadCloud(session.user);showApp()}else render();cloud.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY'){setTimeout(passwordDialog,80)}if(event==='SIGNED_OUT'&&mode==='cloud'){session=null;mode='demo';st=loadLocal();showPublic()}})}catch(err){console.warn('ATLAS network initialization:',err);render();alertUser('Connexion distante momentanément indisponible.')}}}
init();
})();
